css:
/* An answer whose whole body is a drawing — the chip is a LEAD-IN to
   the block beneath it, not a row with content of its own. The
   default 6px bottom margin plus the drawing's own top margin left a
   gap that read as an empty answer; see `components/question.answer`. */
.ansrow.ans-lead { margin-bottom:0; }

/* NORMAL WEIGHT.
   This was font-weight:700 — the whole opening statement of every
   answer set bold. On a page where each answer runs four or five
   lines that is not emphasis, it is a paragraph in bold, and it read
   as though someone had gone over the page. The one thing carrying
   weight in an answer now is the bracketed technical term (b.term);
   the prose around it is ordinary text. The size stays up a little,
   because the opening statement IS the answer and a reader should
   land on it — size says that without shouting. */
.anstext { font-size:18px; line-height:1.68; font-weight:400; }

/* A key term in an answer's opening statement: the author's own
   **bold**, given a soft wash so a student can find it at a glance.
   Painted with box-decoration-break so a term that wraps keeps its
   wash on both lines instead of losing it on the second. */
.anstext b.kw { background:linear-gradient(180deg,transparent 52%,#fdf0a8 52%,#fdf0a8 94%,transparent 94%);
          padding:0 2px; border-radius:2px;
          -webkit-box-decoration-break:clone; box-decoration-break:clone; }

/* A named division inside a long answer. Set as a bold sentence it was
   indistinguishable from the emphasis in the prose around it, so a
   17-block answer had nothing dividing it. The rule above it is what
   does the dividing; the heading only names the part. */
.anssub { font-weight:700; font-size:17px; color:#1f3b6d;
          margin:16px 0 6px; padding-top:9px;
          border-top:1.5px solid #dfe6f2; }
.acol .anssub { font-size:16px; }

/* A key term BEYOND the wash cap: dark and firm, no highlighter.
   The author marked it bold and that is worth keeping, but only the
   first two terms in an answer get the wash — see
   KEYWORD_MAX_PER_ANSWER. Deep ink rather than a background, so a
   paragraph with six terms in it still reads as a paragraph. */
.anstext b.term { color:#123a5e; font-weight:700; }
